module benchmark/solution

import std/string (chars)

pure func encode(n: int, tokens: [(int, string)]) -> string =
  match tokens {
    [] => "",
    token :: rest => match token {
      (value, symbol) =>
        if n >= value then "${symbol}${encode(n - value, tokens)}"
        else encode(n, rest)
    }
  }

export pure func toRoman(n: int) -> string ! {}
requires { n >= 1, n <= 3999 }
{
  encode(n, [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")])
}

pure func symbolValue(symbol: string) -> int =
  match symbol {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func decode(symbols: [string]) -> int =
  match symbols {
    [] => 0,
    symbol :: rest => {
      let value = symbolValue(symbol);
      let next = match rest {
        [] => 0,
        following :: _ => symbolValue(following)
      };
      if value < next then decode(rest) - value
      else value + decode(rest)
    }
  }

export pure func fromRoman(roman: string) -> int =
  decode(chars(roman))

export pure func roundtrip(n: int) -> bool ! {}
requires { n >= 1, n <= 3999 }
ensures { result == true }
{
  fromRoman(toRoman(n)) == n
}

export pure func distinctEncoding(a: int, b: int) -> bool ! {}
requires { a >= 1, a <= 3999, b >= 1, b <= 3999 }
ensures { result == true }
{
  if a == b then true else toRoman(a) != toRoman(b)
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

